options(stringsAsFactors=FALSE,warn=1)
.libPaths(c('D:/R4.5.2/R-4.5.2/library',.libPaths()))
suppressPackageStartupMessages({library(data.table);library(Matrix);library(Seurat)})
setDTthreads(2L)
root<-normalizePath(commandArgs(TRUE)[1],winslash='/');out<-file.path(root,'outputs/MFSD10_表达分布摸底_2026-10-26');old<-file.path(root,'outputs/第一阶段_2026-10-23')
cells<-readRDS(file.path(out,'cache/MFSD10_cell_level.rds'));map<-fread(file.path(old,'metadata/SingleCell_canonical_gene_identity_map.tsv'))
ans<-list()
for(g in c('GSM4909253','GSM4909262','GSM4909281','GSM4909299')){
 so<-readRDS(file.path(old,'cache/seurat_pilot',paste0(g,'_pilot_seurat.rds')));x<-GetAssayData(so,assay='RNA',layer='counts')
 cc<-cells[match(colnames(x),cell_id)];targetrows<-which(map$canonical_id=='ENSG00000109736');stopifnot(identical(rownames(x),map$ensembl_id))
 ans[[g]]<-data.table(gsm=g,n_cells=ncol(x),RNA_layers=paste(Layers(so[['RNA']]),collapse=';'),assays=paste(Assays(so),collapse=';'),target_counts_identical=all(Matrix::colSums(x[targetrows,,drop=FALSE])==cc$MFSD10_counts),RNA_totals_identical=all(Matrix::colSums(x)==cc$RNA_total_UMI),nFeature_identical=all(so$nFeature_RNA==cc$nFeature_RNA))
 rm(so,x);gc(FALSE)
}
fwrite(rbindlist(ans),file.path(out,'audit/Direct_Seurat_RNA_counts_spotcheck.tsv'),sep='\t');stopifnot(all(rbindlist(ans)$target_counts_identical),all(rbindlist(ans)$RNA_totals_identical),all(rbindlist(ans)$nFeature_identical))
b<-fread(file.path(out,'results/Patient_broad_MFSD10_summary.tsv'));e<-fread(file.path(out,'results/Patient_epithelial_MFSD10_summary.tsv'));ma<-cells[epithelial_status=='Malignant_CNV_coherent']
corr<-fread(file.path(out,'results/Malignant_patient_QC_correlations.tsv'));ps<-fread(file.path(out,'results/Malignant_patient_continuous_summary.tsv'))
txt<-capture.output({
 cat('COVERAGE\n');print(cells[,.(cells=.N,patients=uniqueN(patient_id),libraries=uniqueN(gsm)),by=.(tissue_context,preparation)])
 cat('EPITHELIAL STATUS\n');print(cells[cell_type=='Epithelial',.(cells=.N,patients=uniqueN(patient_id),detected=sum(MFSD10_detected),detection_pct=100*mean(MFSD10_detected)),by=.(tissue_context,preparation,epithelial_status)])
 cat('MALIGNANT PATIENTS\n');print(ps[,.(n_patients=.N,n_atleast20=sum(n_cells>=20),all_detection=100*sum(n_detected)/sum(n_cells),median_detection=median(pct_detected),median_detection_min20=median(pct_detected[n_cells>=20]),min_detection_min20=min(pct_detected[n_cells>=20]),max_detection_min20=max(pct_detected[n_cells>=20]),top1_UMI_share=max(MFSD10_UMI)/sum(MFSD10_UMI),top3_UMI_share=sum(head(sort(MFSD10_UMI,decreasing=TRUE),3))/sum(MFSD10_UMI),median_CPM_min20=median(CPM[n_cells>=20]))])
 cat('SMALL MALIGNANT GROUPS\n');print(ps[n_cells<20,.(patient_id,n_cells,n_detected,clinical_labels)])
 cat('QC RHO SUMMARY, >=20 cells & >=5 detected\n');print(corr[adequate_for_description==TRUE,.(n=.N,raw_median=median(rho_raw,na.rm=TRUE),norm_median=median(rho_log_normalized,na.rm=TRUE),norm_min=min(rho_log_normalized,na.rm=TRUE),norm_max=max(rho_log_normalized,na.rm=TRUE),detection_median=median(rho_detection,na.rm=TRUE),n_norm_abs_ge_03=sum(abs(rho_log_normalized)>=.3,na.rm=TRUE)),by=.(scope,covariate)])
 cat('MALIGNANT BY CLINICAL LABEL: DESCRIPTIVE ONLY\n');print(e[epithelial_status=='Malignant_CNV_coherent',.(patients=uniqueN(patient_id),patients_min20=uniqueN(patient_id[n_cells>=20]),cells=sum(n_cells),patient_median_detection=median(pct_detected[n_cells>=20])),by=clinical_label])
 cat('MALIGNANT TOP PATIENTS\n');print(ps[order(-MFSD10_UMI)][1:5,.(patient_id,n_cells,n_detected,MFSD10_UMI,pct_detected,CPM)])
 cat('ALL PRIMARY CELLTYPE COVERAGE\n');print(b[tissue_context=='Primary_tumor',.(cell_type,n_cells,n_expressing)][,.(n_cells=sum(n_cells),n_detected=sum(n_expressing)),by=cell_type])
 cat('TMM VS CPM MALIGNANT\n');z<-e[epithelial_status=='Malignant_CNV_coherent' & n_cells>=20];print(z[,.(rho=cor(CPM,TMM_CPM,method='spearman'),median_CPM=median(CPM),median_TMM_CPM=median(TMM_CPM))])
 cat('ALL SOURCE FILES\n');print(nrow(fread(file.path(out,'audit/Read_only_input_manifest.tsv'))))
})
writeLines(txt,file.path(out,'results/Descriptive_digest.txt'));cat(paste(txt,collapse='\n'),'\n')
capture.output(sessionInfo(),file=file.path(out,'logs/03_sessionInfo.txt'))
